    compromissoPratico: `Balanço do ano: leiam juntos a lista dos 52 temas semanais (ou relembrem as que mais marcaram). Depois escrevam juntos três frases: (1) O que aprendemos sobre Deus neste ano; (2) O que mudou no nosso casamento; (3) O que queremos cultivar no próximo ano. Guardem esse registro.`,
