    tipo: 'mesa-alianca',
    perguntaGeradora: `Ao final de um ano inteiro de Palavra e aliança: que versículo ou promessa transformou mais o casamento de vocês? Que área do lar foi mais renovada pela leitura da Bíblia juntos este ano?`,
    oracaoAlianca: `Pai, chegamos ao fim do ano — mas não ao fim da história. Tu fazes novas todas as coisas. Obrigado por cada capítulo lido, cada questão honesta, cada oração que subiu como incenso ao teu trono. O casamento de vocês é teu. O Cordeiro reina. Jesus vem em breve. A graça do Senhor Jesus seja com o nosso lar — agora e para sempre. Amém. Vem, Senhor Jesus.`,
